package com.ray.service.impl;
import com.ray.exception.BusinessException;import com.ray.mapper.UserVoucherMapper;import com.ray.service.*;import com.ray.vo.VoucherQrTokenVO;import java.time.LocalDateTime;import java.util.UUID;import java.util.concurrent.TimeUnit;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Service;
@Service public class VoucherQrTokenServiceImpl implements VoucherQrTokenService {private final UserVoucherMapper mapper;private final CurrentUserProvider user;private final StringRedisTemplate redis;public VoucherQrTokenServiceImpl(UserVoucherMapper mapper,CurrentUserProvider user,StringRedisTemplate redis){this.mapper=mapper;this.user=user;this.redis=redis;}public VoucherQrTokenVO issue(Long id){var v=mapper.selectOne(new com.baomidou.mybatisplus.core.conditions.query.QueryWrapper<com.ray.entity.UserVoucher>().eq("id",id).eq("user_id",user.requireUserId()));if(v==null)throw BusinessException.notFound("USER_VOUCHER_NOT_FOUND","用户券不存在");String t=UUID.randomUUID().toString().replace("-","");redis.opsForValue().set("roamly:qr:voucher:"+t,id+"|"+user.requireUserId(),60,TimeUnit.SECONDS);return new VoucherQrTokenVO(t,LocalDateTime.now().plusSeconds(60));}public String consume(String t){if(t==null||t.isBlank())throw BusinessException.badRequest("QR_TOKEN_INVALID","二维码令牌无效");String v=redis.opsForValue().getAndDelete("roamly:qr:voucher:"+t);if(v==null)throw BusinessException.conflict("QR_TOKEN_EXPIRED","二维码已过期或已使用");return v;}}
